import random
import time

class Virus:
    def __init__(self, name, spread_rate):
        self.name = name
        self.spread_rate = spread_rate
        self.infected_devices = []

    def infect(self, device):
        if random.randint(0, 100) < self.spread_rate:
            self.infected_devices.append(device)
            print(f"{self.name} infecting {device}")
        else:
            print(f"{self.name} doesn't infect {device}")

class Malware:
    def __init__(self, name, transmission_rate):
        self.name = name
        self.transmission_rate = transmission_rate
        self.infected_devices = []

    def spread(self, device):
        if random.randint(0, 100) < self.transmission_rate:
            self.infected_devices.append(device)
            print(f"{self.name} spreading to {device}")
        else:
            print(f"{self.name} doesn't spread to {device}")

class Network(object):
    def __init__(self):
        self.devices = []

    def add_device(self, device):
        self.devices.append(device)

    def get_infected(self):
        infected = []
        for device in self.devices:
            if device in Virus.infected_devices:
                infected.append(device)
        return infected

